package com.nelja.urqr.menu.item;
import java.util.*; import org.springframework.data.jpa.repository.JpaRepository;import org.springframework.data.jpa.repository.Query;import org.springframework.data.repository.query.Param;
public interface MenuItemRepository extends JpaRepository<MenuItem,UUID>{Optional<MenuItem> findByIdAndHotelIdAndActiveTrue(UUID id,UUID hotelId);List<MenuItem> findAllByHotelIdAndIdIn(UUID hotelId,java.util.Collection<UUID> ids);@Query("select i from MenuItem i where i.hotelId=:hotel and i.active=true and (:category is null or i.categoryId=:category) and exists (select c.id from MenuCategory c where c.id=i.categoryId and c.hotelId=i.hotelId and c.active=true) order by i.name")List<MenuItem> findPosMenu(@Param("hotel")UUID hotel,@Param("category")UUID category);}
